package com.nextcandle.ai; import java.util.*; public final class CandleSequenceBuilder{public static final int TARGET=15;public List<Candle>buildFromImage(int[]gray,int w,int h){List<Candle>out=new ArrayList<>();if(gray==null||w<64||h<64)return out;int top=h/8,bottom=h*7/8,left=w/12,right=w*11/12;int cols=15,sliceW=Math.max(4,(right-left)/cols);double base=100;for(int cc=0;cc<cols;cc++){int x0=left+cc*sliceW,x1=Math.min(right,x0+sliceW),minY=bottom,maxY=top;long n=0;for(int y=top;y<bottom;y++)for(int x=x0;x<x1;x++){int g=gray[y*w+x]&255;if(g>175||g<70){minY=Math.min(minY,y);maxY=Math.max(maxY,y);n++;}}if(maxY<=minY||n<6)continue;double range=Math.max(1,maxY-minY),center=(maxY+minY)*.5;double open=base+(center-minY)*.01,close=base+(center-maxY)*.01,high=Math.max(open,close)+range*.01,low=Math.min(open,close)-range*.01;out.add(new Candle(open,high,low,close,n,System.currentTimeMillis()));}return out;}}
